430          | HID6 '/' NUM          {
   431                                    CHECK_PTR_VAL($1);
   432  #ifdef INET6
   433                                    CHECK_PTR_VAL(($$.b = gen_mcode6(cstate, $1, NULL, $3,
   434                                      $$.q = $<blk>0.q)));
   435  #else
   436                                    bpf_set_error(cstate, "'ip6addr/prefixlen' not supported "
   437                                          "in this configuration");
   438                                    YYABORT;
   439  #endif /*INET6*/
   440                                  }
   441          | HID6                  {
   442                                    CHECK_PTR_VAL($1);
   443  #ifdef INET6
   444                                    CHECK_PTR_VAL(($$.b = gen_mcode6(cstate, $1, 0, 128,
   445                                      $$.q = $<blk>0.q)));
   446  #else
   447                                    bpf_set_error(cstate, "'ip6addr' not supported "
   448                                          "in this configuration");
   449                                    YYABORT;
   450  #endif /*INET6*/
   451                                  }
   452          | EID                   { CHECK_PTR_VAL($1); CHECK_PTR_VAL(($$.b = gen_ecode(cstate, $1, $$.q = $<blk>0.q))); }
   453          | AID                   { CHECK_PTR_VAL($1); CHECK_PTR_VAL(($$.b = gen_acode(cstate, $1, $$.q = $<blk>0.q))); }
   454          | not id                { gen_not($2.b); $$ = $2; }
   455          ;
   456  not:      '!'                   { $$ = $<blk>0; }
   457          ;
   458  paren:    '('                   { $$ = $<blk>0; }
   459          ;
   460  pid:      nid
   461          | qid and id            { gen_and($1.b, $3.b); $$ = $3; }
   462          | qid or id             { gen_or($1.b, $3.b); $$ = $3; }
   463          ;
   464  qid:      pnum                  { CHECK_PTR_VAL(($$.b = gen_ncode(cstate, NULL, (bpf_u_int32)$1,
   465                                                     $$.q = $<blk>0.q))); }
   466          | pid
   467          ;
   468  term:     rterm
   469          | not term              { gen_not($2.b); $$ = $2; }
   470          ;
   471  head:     pqual dqual aqual     { QSET($$.q, $1, $2, $3); }
   472          | pqual dqual           { QSET($$.q, $1, $2, Q_DEFAULT); }
   473          | pqual aqual           { QSET($$.q, $1, Q_DEFAULT, $2); }
   474          | pqual PROTO           { QSET($$.q, $1, Q_DEFAULT, Q_PROTO); }
   475          | pqual PROTOCHAIN      {
   476  #ifdef NO_PROTOCHAIN
   477                                    bpf_set_error(cstate, "protochain not supported");
   478                                    YYABORT;
   479  #else
   480                                    QSET($$.q, $1, Q_DEFAULT, Q_PROTOCHAIN);
   481  #endif
   482                                  }
   483          | pqual ndaqual         { QSET($$.q, $1, Q_DEFAULT, $2); }
   484          ;
   485  rterm:    head id               { $$ = $2; }
   486          | paren expr ')'        { $$.b = $2.b; $$.q = $1.q; }
   487          | pname                 { CHECK_PTR_VAL(($$.b = gen_proto_abbrev(cstate, $1))); $$.q = qerr; }
   488          | arth relop arth       { CHECK_PTR_VAL(($$.b = gen_relation(cstate, $2, $1, $3, 0)));
   489                                    $$.q = qerr; }
   490          | arth irelop arth      { CHECK_PTR_VAL(($$.b = gen_relation(cstate, $2, $1, $3, 1)));
   491                                    $$.q = qerr; }
   492          | other                 { $$.b = $1; $$.q = qerr; }
   493          | atmtype               { CHECK_PTR_VAL(($$.b = gen_atmtype_abbrev(cstate, $1))); $$.q = qerr; }
   494          | atmmultitype          { CHECK_PTR_VAL(($$.b = gen_atmmulti_abbrev(cstate, $1))); $$.q = qerr; }
   495          | atmfield atmvalue     { $$.b = $2.b; $$.q = qerr; }
   496          | mtp2type              { CHECK_PTR_VAL(($$.b = gen_mtp2type_abbrev(cstate, $1))); $$.q = qerr; }
   497          | mtp3field mtp3value   { $$.b = $2.b; $$.q = qerr; }
   498          ;
   499  /* protocol level qualifiers */
   500  pqual:    pname
   501          |                       { $$ = Q_DEFAULT; }
   502          ;
   503  /* 'direction' qualifiers */
   504  dqual:    SRC                   { $$ = Q_SRC; }
   505          | DST                   { $$ = Q_DST; }
   506          | SRC OR DST            { $$ = Q_OR; }
   507          | DST OR SRC            { $$ = Q_OR; }
   508          | SRC AND DST           { $$ = Q_AND; }
   509          | DST AND SRC           { $$ = Q_AND; }
   510          | ADDR1                 { $$ = Q_ADDR1; }
   511          | ADDR2                 { $$ = Q_ADDR2; }
   512          | ADDR3                 { $$ = Q_ADDR3; }
   513          | ADDR4                 { $$ = Q_ADDR4; }
   514          | RA                    { $$ = Q_RA; }
   515          | TA                    { $$ = Q_TA; }
   516          ;
   517  /* address type qualifiers */
   518  aqual:    HOST                  { $$ = Q_HOST; }
   519          | NET                   { $$ = Q_NET; }
   520          | PORT                  { $$ = Q_PORT; }
   521          | PORTRANGE             { $$ = Q_PORTRANGE; }
   522          ;
   523  /* non-directional address type qualifiers */
   524  ndaqual:  GATEWAY               { $$ = Q_GATEWAY; }
   525          ;
   526  pname:    LINK                  { $$ = Q_LINK; }
   527          | IP                    { $$ = Q_IP; }
   528          | ARP                   { $$ = Q_ARP; }
   529          | RARP                  { $$ = Q_RARP; }
   530          | SCTP                  { $$ = Q_SCTP; }
   531          | TCP                   { $$ = Q_TCP; }
   532          | UDP                   { $$ = Q_UDP; }
   533          | ICMP                  { $$ = Q_ICMP; }
   534          | IGMP                  { $$ = Q_IGMP; }
   535          | IGRP                  { $$ = Q_IGRP; }
   536          | PIM                   { $$ = Q_PIM; }
   537          | VRRP                  { $$ = Q_VRRP; }
   538          | CARP                  { $$ = Q_CARP; }
   539          | ATALK                 { $$ = Q_ATALK; }
   540          | AARP                  { $$ = Q_AARP; }
   541          | DECNET                { $$ = Q_DECNET; }
   542          | LAT                   { $$ = Q_LAT; }
   543          | SCA                   { $$ = Q_SCA; }
   544          | MOPDL                 { $$ = Q_MOPDL; }
   545          | MOPRC                 { $$ = Q_MOPRC; }
   546          | IPV6                  { $$ = Q_IPV6; }
   547          | ICMPV6                { $$ = Q_ICMPV6; }
   548          | AH                    { $$ = Q_AH; }
   549          | ESP                   { $$ = Q_ESP; }
   550          | ISO                   { $$ = Q_ISO; }
   551          | ESIS                  { $$ = Q_ESIS; }
   552          | ISIS                  { $$ = Q_ISIS; }
   553          | L1                    { $$ = Q_ISIS_L1; }
   554          | L2                    { $$ = Q_ISIS_L2; }
   555          | IIH                   { $$ = Q_ISIS_IIH; }
   556          | LSP                   { $$ = Q_ISIS_LSP; }
   557          | SNP                   { $$ = Q_ISIS_SNP; }
   558          | PSNP                  { $$ = Q_ISIS_PSNP; }
   559          | CSNP                  { $$ = Q_ISIS_CSNP; }
   560          | CLNP                  { $$ = Q_CLNP; }
   561          | STP                   { $$ = Q_STP; }
   562          | IPX                   { $$ = Q_IPX; }
   563          | NETBEUI               { $$ = Q_NETBEUI; }
   564          | RADIO                 { $$ = Q_RADIO; }
   565          ;
   566  other:    pqual TK_BROADCAST    { CHECK_PTR_VAL(($$ = gen_broadcast(cstate, $1))); }
   567          | pqual TK_MULTICAST    { CHECK_PTR_VAL(($$ = gen_multicast(cstate, $1))); }
   568          | LESS NUM              { CHECK_PTR_VAL(($$ = gen_less(cstate, $2))); }
   569          | GREATER NUM           { CHECK_PTR_VAL(($$ = gen_greater(cstate, $2))); }
   570          | CBYTE NUM byteop NUM  { CHECK_PTR_VAL(($$ = gen_byteop(cstate, $3, $2, $4))); }
   571          | INBOUND               { CHECK_PTR_VAL(($$ = gen_inbound(cstate, 0))); }
   572          | OUTBOUND              { CHECK_PTR_VAL(($$ = gen_inbound(cstate, 1))); }
   573          | VLAN pnum             { CHECK_PTR_VAL(($$ = gen_vlan(cstate, (bpf_u_int32)$2, 1))); }
   574          | VLAN                  { CHECK_PTR_VAL(($$ = gen_vlan(cstate, 0, 0))); }
   575          | MPLS pnum             { CHECK_PTR_VAL(($$ = gen_mpls(cstate, (bpf_u_int32)$2, 1))); }
   576          | MPLS                  { CHECK_PTR_VAL(($$ = gen_mpls(cstate, 0, 0))); }
   577          | PPPOED                { CHECK_PTR_VAL(($$ = gen_pppoed(cstate))); }
   578          | PPPOES pnum           { CHECK_PTR_VAL(($$ = gen_pppoes(cstate, (bpf_u_int32)$2, 1))); }
   579          | PPPOES                { CHECK_PTR_VAL(($$ = gen_pppoes(cstate, 0, 0))); }
   580          | GENEVE pnum           { CHECK_PTR_VAL(($$ = gen_geneve(cstate, (bpf_u_int32)$2, 1))); }
   581          | GENEVE                { CHECK_PTR_VAL(($$ = gen_geneve(cstate, 0, 0))); }
   582          | pfvar                 { $$ = $1; }
   583          | pqual p80211          { $$ = $2; }
   584          | pllc                  { $$ = $1; }
   585          ;
   586
   587  pfvar:    PF_IFNAME ID          { CHECK_PTR_VAL($2); CHECK_PTR_VAL(($$ = gen_pf_ifname(cstate, $2))); }
   588          | PF_RSET ID            { CHECK_PTR_VAL($2); CHECK_PTR_VAL(($$ = gen_pf_ruleset(cstate, $2))); }
   589          | PF_RNR NUM            { CHECK_PTR_VAL(($$ = gen_pf_rnr(cstate, $2))); }
   590          | PF_SRNR NUM           { CHECK_PTR_VAL(($$ = gen_pf_srnr(cstate, $2))); }
   591          | PF_REASON reason      { CHECK_PTR_VAL(($$ = gen_pf_reason(cstate, $2))); }
   592          | PF_ACTION action      { CHECK_PTR_VAL(($$ = gen_pf_action(cstate, $2))); }
   593          ;
   594
   595  p80211:   TYPE type SUBTYPE subtype
   596                                  { CHECK_PTR_VAL(($$ = gen_p80211_type(cstate, $2 | $4,
   597                                          IEEE80211_FC0_TYPE_MASK |
   598                                          IEEE80211_FC0_SUBTYPE_MASK)));
   599                                  }
   600          | TYPE type             { CHECK_PTR_VAL(($$ = gen_p80211_type(cstate, $2,
   601                                          IEEE80211_FC0_TYPE_MASK)));
   602                                  }
   603          | SUBTYPE type_subtype  { CHECK_PTR_VAL(($$ = gen_p80211_type(cstate, $2,
   604                                          IEEE80211_FC0_TYPE_MASK |
   605                                          IEEE80211_FC0_SUBTYPE_MASK)));
   606                                  }
   607          | DIR dir               { CHECK_PTR_VAL(($$ = gen_p80211_fcdir(cstate, $2))); }
   608          ;
   609
   610  type:     NUM
   611          | ID                    { CHECK_PTR_VAL($1);
   612                                    $$ = str2tok($1, ieee80211_types);
   613                                    if ($$ == -1) {
   614                                          bpf_set_error(cstate, "unknown 802.11 type name");
   615                                          YYABORT;
   616                                    }
   617                                  }
   618          ;
   619
   620  subtype:  NUM
487:    | pname                 { CHECK_PTR_VAL(($$.b = gen_proto_abbrev(cstate, $1))); $$.q = qerr; }
